  1→package jlsm.table;
  2→
  3→import java.io.IOException;
  4→import java.util.Iterator;
  5→import java.util.List;
  6→import java.util.Objects;
  7→
  8→/**
  9→ * Fluent query builder for table lookups. Builds a {@link Predicate} tree and executes it against
 10→ * the table's indices and data.
 11→ *
 12→ * <p>
 13→ * Usage:
 14→ *
 15→ * <pre>{@code
 16→ * Iterator<TableEntry<String>> results = table.query().where("age").gt(30).and("status")
 17→ *         .eq("active").execute();
 18→ * }</pre>
 19→ *
 20→ * <p>
 21→ * Contract:
 22→ * <ul>
 23→ * <li>Receives: field names and values via fluent chaining</li>
 24→ * <li>Returns: {@code Iterator<TableEntry<K>>} on execute()</li>
 25→ * <li>Side effects: none until execute() — query building is pure</li>
 26→ * <li>Error conditions: IllegalArgumentException on invalid field/type combinations</li>
 27→ * </ul>
 28→ *
 29→ * @param <K> the primary key type (String or Long)
 30→ */
 31→public final class TableQuery<K> {
 32→
 33→    private enum CombineMode {
 34→        NONE, AND, OR
 35→    }
 36→
 37→    private Predicate root;
 38→    private CombineMode nextMode = CombineMode.NONE;
 39→
 40→    private TableQuery() {
 41→    }
 42→
 43→    /**
 44→     * Begins a predicate on the given field.
 45→     *
 46→     * @param fieldName the field to filter on
 47→     * @return a field clause for specifying the comparison operator
 48→     */
 49→    public FieldClause<K> where(String fieldName) {
 50→        Objects.requireNonNull(fieldName, "fieldName");
 51→        return new FieldClause<>(this, fieldName);
 52→    }
 53→
 54→    /**
 55→     * Executes the query, returning matching entries. Uses available indices where possible; falls
 56→     * back to scan-and-filter.
 57→     *
 58→     * @return iterator over matching table entries
 59→     * @throws IOException if an I/O error occurs during query execution
 60→     */
 61→    public Iterator<TableEntry<K>> execute() throws IOException {
 62→        throw new UnsupportedOperationException(
 63→                "execute() requires table binding — use table.query() to obtain a bound instance");
 64→    }
 65→
 66→    /**
 67→     * Returns the predicate tree built so far. Useful for inspection, serialization, or future SQL
 68→     * translation.
 69→     *
 70→     * @return the root predicate, or null if no predicates have been added
 71→     */
 72→    public Predicate predicate() {
 73→        return root;
 74→    }
 75→
 76→    /**
 77→     * Chains an AND predicate on the given field.
 78→     *
 79→     * @param fieldName the next field to filter on
 80→     * @return a field clause for specifying the comparison operator
 81→     */
 82→    public FieldClause<K> and(String fieldName) {
 83→        Objects.requireNonNull(fieldName, "fieldName");
 84→        nextMode = CombineMode.AND;
 85→        return new FieldClause<>(this, fieldName);
 86→    }
 87→
 88→    /**
 89→     * Chains an OR predicate on the given field.
 90→     *
 91→     * @param fieldName the next field to filter on
 92→     * @return a field clause for specifying the comparison operator
 93→     */
 94→    public FieldClause<K> or(String fieldName) {
 95→        Objects.requireNonNull(fieldName, "fieldName");
 96→        nextMode = CombineMode.OR;
 97→        return new FieldClause<>(this, fieldName);
 98→    }
 99→
100→    TableQuery<K> addPredicate(Predicate predicate) {
101→        assert predicate != null : "predicate must not be null";
102→        if (root == null || nextMode == CombineMode.NONE) {
103→            root = predicate;
104→        } else if (nextMode == CombineMode.AND) {
105→            root = new Predicate.And(List.of(root, predicate));
106→        } else {
107→            root = new Predicate.Or(List.of(root, predicate));
108→        }
109→        nextMode = CombineMode.NONE;
110→        return this;
111→    }
112→
113→    /**
114→     * A field-level clause that provides comparison operators.
115→     *
116→     * @param <K> the primary key type
117→     */
118→    public static final class FieldClause<K> {
119→
120→        private final TableQuery<K> query;
121→        private final String fieldName;
122→
123→        FieldClause(TableQuery<K> query, String fieldName) {
124→            assert query != null : "query must not be null";
125→            assert fieldName != null : "fieldName must not be null";
126→            this.query = query;
127→            this.fieldName = fieldName;
128→        }
129→
130→        /** Equality: field == value. */
131→        public TableQuery<K> eq(Object value) {
132→            return query.addPredicate(new Predicate.Eq(fieldName, value));
133→        }
134→
135→        /** Inequality: field != value. */
136→        public TableQuery<K> ne(Object value) {
137→            return query.addPredicate(new Predicate.Ne(fieldName, value));
138→        }
139→
140→        /** Greater than: field > value. */
141→        public TableQuery<K> gt(Comparable<?> value) {
142→            return query.addPredicate(new Predicate.Gt(fieldName, value));
143→        }
144→
145→        /** Greater than or equal: field >= value. */
146→        public TableQuery<K> gte(Comparable<?> value) {
147→            return query.addPredicate(new Predicate.Gte(fieldName, value));
148→        }
149→
150→        /** Less than: field < value. */
151→        public TableQuery<K> lt(Comparable<?> value) {
152→            return query.addPredicate(new Predicate.Lt(fieldName, value));
153→        }
154→
155→        /** Less than or equal: field <= value. */
156→        public TableQuery<K> lte(Comparable<?> value) {
157→            return query.addPredicate(new Predicate.Lte(fieldName, value));
158→        }
159→
160→        /** Range: low <= field <= high. */
161→        public TableQuery<K> between(Comparable<?> low, Comparable<?> high) {
162→            return query.addPredicate(new Predicate.Between(fieldName, low, high));
163→        }
164→
165→        /** Full-text search on this field. */
166→        public TableQuery<K> fullTextMatch(String queryText) {
167→            return query.addPredicate(new Predicate.FullTextMatch(fieldName, queryText));
168→        }
169→
170→        /** Vector nearest-neighbour search on this field. */
171→        public TableQuery<K> vectorNearest(float[] queryVector, int topK) {
172→            return query.addPredicate(new Predicate.VectorNearest(fieldName, queryVector, topK));
173→        }
174→    }
175→}
