  1→package jlsm.table.internal;
  2→
  3→import java.io.IOException;
  4→import java.lang.foreign.MemorySegment;
  5→import java.lang.foreign.ValueLayout;
  6→import java.nio.charset.StandardCharsets;
  7→import java.util.ArrayList;
  8→import java.util.Arrays;
  9→import java.util.Iterator;
 10→import java.util.LinkedHashSet;
 11→import java.util.List;
 12→import java.util.Objects;
 13→import java.util.Set;
 14→
 15→import jlsm.table.JlsmSchema;
 16→import jlsm.table.Predicate;
 17→import jlsm.table.TableEntry;
 18→
 19→/**
 20→ * Plans and executes queries against a table's indices and data.
 21→ *
 22→ * <p>
 23→ * Contract:
 24→ * <ul>
 25→ * <li>Receives: a Predicate tree, an IndexRegistry, and access to the main table data</li>
 26→ * <li>Returns: Iterator of matching TableEntry instances</li>
 27→ * <li>For each leaf predicate, checks IndexRegistry for a matching index</li>
 28→ * <li>Index-backed predicates use index lookup; others fall back to scan-and-filter</li>
 29→ * <li>And: intersects results from children</li>
 30→ * <li>Or: unions results from children</li>
 31→ * <li>Error conditions: IOException on I/O errors during execution</li>
 32→ * </ul>
 33→ *
 34→ * @param <K> the primary key type (String or Long)
 35→ */
 36→public final class QueryExecutor<K> {
 37→
 38→    private final JlsmSchema schema;
 39→    private final IndexRegistry indexRegistry;
 40→
 41→    /**
 42→     * Creates a query executor.
 43→     *
 44→     * @param schema the table's schema (for field type resolution)
 45→     * @param indexRegistry the table's index registry
 46→     */
 47→    public QueryExecutor(JlsmSchema schema, IndexRegistry indexRegistry) {
 48→        Objects.requireNonNull(schema, "schema");
 49→        Objects.requireNonNull(indexRegistry, "indexRegistry");
 50→        this.schema = schema;
 51→        this.indexRegistry = indexRegistry;
 52→    }
 53→
 54→    /**
 55→     * Executes the given predicate and returns matching entries.
 56→     *
 57→     * @param predicate the predicate to evaluate
 58→     * @return iterator over matching table entries
 59→     * @throws IOException on I/O error
 60→     */
 61→    public Iterator<TableEntry<K>> execute(Predicate predicate) throws IOException {
 62→        Objects.requireNonNull(predicate, "predicate");
 63→        Set<PkKey> matchingKeys = executePredicate(predicate);
 64→        List<TableEntry<K>> results = new ArrayList<>(matchingKeys.size());
 65→        for (PkKey pk : matchingKeys) {
 66→            IndexRegistry.StoredEntry stored = indexRegistry.resolveEntry(toSegment(pk));
 67→            if (stored != null) {
 68→                @SuppressWarnings("unchecked")
 69→                K key = (K) decodeKey(stored.primaryKey());
 70→                results.add(new TableEntry<>(key, stored.document()));
 71→            }
 72→        }
 73→        return results.iterator();
 74→    }
 75→
 76→    // ── Query planning ──────────────────────────────────────────────────
 77→
 78→    private Set<PkKey> executePredicate(Predicate predicate) throws IOException {
 79→        return switch (predicate) {
 80→            case Predicate.And and -> executeAnd(and);
 81→            case Predicate.Or or -> executeOr(or);
 82→            default -> executeLeaf(predicate);
 83→        };
 84→    }
 85→
 86→    private Set<PkKey> executeAnd(Predicate.And and) throws IOException {
 87→        Set<PkKey> result = null;
 88→        for (Predicate child : and.children()) {
 89→            Set<PkKey> childResult = executePredicate(child);
 90→            if (result == null) {
 91→                result = new LinkedHashSet<>(childResult);
 92→            } else {
 93→                result.retainAll(childResult);
 94→            }
 95→        }
 96→        return result != null ? result : Set.of();
 97→    }
 98→
 99→    private Set<PkKey> executeOr(Predicate.Or or) throws IOException {
100→        Set<PkKey> result = new LinkedHashSet<>();
101→        for (Predicate child : or.children()) {
102→            result.addAll(executePredicate(child));
103→        }
104→        return result;
105→    }
106→
107→    private Set<PkKey> executeLeaf(Predicate predicate) throws IOException {
108→        SecondaryIndex index = indexRegistry.findIndex(predicate);
109→        if (index != null) {
110→            Set<PkKey> keys = new LinkedHashSet<>();
111→            Iterator<MemorySegment> it = index.lookup(predicate);
112→            while (it.hasNext()) {
113→                keys.add(toPkKey(it.next()));
114→            }
115→            return keys;
116→        }
117→        return scanAndFilter(predicate);
118→    }
119→
120→    private Set<PkKey> scanAndFilter(Predicate predicate) {
121→        Set<PkKey> result = new LinkedHashSet<>();
122→        Iterator<IndexRegistry.StoredEntry> it = indexRegistry.allEntries();
123→        while (it.hasNext()) {
124→            IndexRegistry.StoredEntry entry = it.next();
125→            if (matchesPredicate(entry, predicate)) {
126→                result.add(toPkKey(entry.primaryKey()));
127→            }
128→        }
129→        return result;
130→    }
131→
132→    @SuppressWarnings("unchecked")
133→    private boolean matchesPredicate(IndexRegistry.StoredEntry entry, Predicate predicate) {
134→        return switch (predicate) {
135→            case Predicate.Eq eq -> {
136→                Object fieldValue = extractFieldValue(entry, eq.field());
137→                yield fieldValue != null && fieldValue.equals(eq.value());
138→            }
139→            case Predicate.Ne ne -> {
140→                Object fieldValue = extractFieldValue(entry, ne.field());
141→                yield fieldValue != null && !fieldValue.equals(ne.value());
142→            }
143→            case Predicate.Gt gt -> {
144→                Object fieldValue = extractFieldValue(entry, gt.field());
145→                yield fieldValue instanceof Comparable c && c.compareTo(gt.value()) > 0;
146→            }
147→            case Predicate.Gte gte -> {
148→                Object fieldValue = extractFieldValue(entry, gte.field());
149→                yield fieldValue instanceof Comparable c && c.compareTo(gte.value()) >= 0;
150→            }
151→            case Predicate.Lt lt -> {
152→                Object fieldValue = extractFieldValue(entry, lt.field());
153→                yield fieldValue instanceof Comparable c && c.compareTo(lt.value()) < 0;
154→            }
155→            case Predicate.Lte lte -> {
156→                Object fieldValue = extractFieldValue(entry, lte.field());
157→                yield fieldValue instanceof Comparable c && c.compareTo(lte.value()) <= 0;
158→            }
159→            case Predicate.Between between -> {
160→                Object fieldValue = extractFieldValue(entry, between.field());
161→                yield fieldValue instanceof Comparable c && c.compareTo(between.low()) >= 0
162→                        && c.compareTo(between.high()) <= 0;
163→            }
164→            case Predicate.FullTextMatch _, Predicate.VectorNearest _ -> false;
165→            case Predicate.And _, Predicate.Or _ -> false;
166→        };
167→    }
168→
169→    private Object extractFieldValue(IndexRegistry.StoredEntry entry, String fieldName) {
170→        var document = entry.document();
171→        if (document.isNull(fieldName)) {
172→            return null;
173→        }
174→        int idx = schema.fieldIndex(fieldName);
175→        assert idx >= 0 : "Field must exist in schema";
176→        var fieldDef = schema.fields().get(idx);
177→        var fieldType = fieldDef.type();
178→
179→        if (fieldType instanceof jlsm.table.FieldType.Primitive p) {
180→            return switch (p) {
181→                case STRING -> document.getString(fieldName);
182→                case INT8 -> document.getByte(fieldName);
183→                case INT16 -> document.getShort(fieldName);
184→                case INT32 -> document.getInt(fieldName);
185→                case INT64 -> document.getLong(fieldName);
186→                case FLOAT16 -> document.getFloat16Bits(fieldName);
187→                case FLOAT32 -> document.getFloat(fieldName);
188→                case FLOAT64 -> document.getDouble(fieldName);
189→                case BOOLEAN -> document.getBoolean(fieldName);
190→                case TIMESTAMP -> document.getTimestamp(fieldName);
191→            };
192→        }
193→        return null;
194→    }
195→
196→    // ── Key encoding helpers ────────────────────────────────────────────
197→
198→    private static Object decodeKey(MemorySegment pk) {
199→        return new String(pk.toArray(ValueLayout.JAVA_BYTE), StandardCharsets.UTF_8);
200→    }
201→
202→    private record PkKey(byte[] data) {
203→        @Override
204→        public boolean equals(Object obj) {
205→            return obj instanceof PkKey other && Arrays.equals(this.data, other.data);
206→        }
207→
208→        @Override
209→        public int hashCode() {
210→            return Arrays.hashCode(data);
211→        }
212→    }
213→
214→    private static PkKey toPkKey(MemorySegment seg) {
215→        return new PkKey(seg.toArray(ValueLayout.JAVA_BYTE));
216→    }
217→
218→    private static MemorySegment toSegment(PkKey pk) {
219→        var seg = java.lang.foreign.Arena.ofAuto().allocate(pk.data.length);
220→        MemorySegment.copy(pk.data, 0, seg, ValueLayout.JAVA_BYTE, 0, pk.data.length);
221→        return seg;
222→    }
223→}
