 7→/**
 8→ * Defines a secondary index on a table field.
 9→ *
10→ * <p>
11→ * Contract:
12→ * <ul>
13→ * <li>Receives: field name, index type, and optional configuration for vector indices</li>
14→ * <li>Returns: immutable definition used by the table builder to create the index</li>
15→ * <li>Side effects: none — pure value holder</li>
16→ * <li>Validated at table build time against the schema</li>
17→ * </ul>
18→ *
19→ * @param fieldName the schema field to index — must exist in the table's schema
20→ * @param indexType the type of index to create
21→ * @param vectorDimensions number of dimensions for VECTOR indices; ignored for other types
22→ * @param similarityFunction similarity function for VECTOR indices; ignored for other types
23→ */
24→public record IndexDefinition(String fieldName, IndexType indexType, int vectorDimensions,
25→        SimilarityFunction similarityFunction) {
26→
27→    /**
28→     * Creates an index definition for non-vector index types.
29→     */
30→    public IndexDefinition(String fieldName, IndexType indexType) {
31→        this(fieldName, indexType, 0, null);
32→    }
33→
34→    public IndexDefinition {
35→        Objects.requireNonNull(fieldName, "fieldName");
36→        Objects.requireNonNull(indexType, "indexType");
37→        if (fieldName.isBlank()) {
38→            throw new IllegalArgumentException("fieldName must not be blank");
39→        }
40→        if (indexType == IndexType.VECTOR) {
41→            if (vectorDimensions <= 0) {
42→                throw new IllegalArgumentException(
43→                        "vectorDimensions must be positive for VECTOR indices");
44→            }
45→            Objects.requireNonNull(similarityFunction,
46→                    "similarityFunction required for VECTOR indices");
47→        }
48→    }
49→}
