  1→package jlsm.table;
  2→
  3→import java.util.List;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * Represents the type of a field in a {@link JlsmSchema}.
  8→ *
  9→ * <p>
 10→ * FieldType is a sealed interface with three permitted implementations:
 11→ * <ul>
 12→ * <li>{@link Primitive} — an enum of scalar types</li>
 13→ * <li>{@link ArrayType} — a homogeneous array of a given element type</li>
 14→ * <li>{@link ObjectType} — a nested object with its own field definitions</li>
 15→ * </ul>
 16→ */
 17→public sealed interface FieldType
 18→        permits FieldType.Primitive, FieldType.ArrayType, FieldType.ObjectType {
 19→
 20→    /** Scalar primitive field types. */
 21→    enum Primitive implements FieldType {
 22→        STRING, INT8, INT16, INT32, INT64, FLOAT16, FLOAT32, FLOAT64, BOOLEAN, TIMESTAMP
 23→    }
 24→
 25→    /**
 26→     * A homogeneous array of elements, all sharing the same {@link FieldType}.
 27→     *
 28→     * @param elementType the type of each element in the array; must not be null
 29→     */
 30→    record ArrayType(FieldType elementType) implements FieldType {
 31→        public ArrayType {
 32→            Objects.requireNonNull(elementType, "elementType must not be null");
 33→        }
 34→    }
 35→
 36→    /**
 37→     * A nested object type with an ordered list of named fields.
 38→     *
 39→     * @param fields the field definitions of the nested object; must not be null
 40→     */
 41→    record ObjectType(List<FieldDefinition> fields) implements FieldType {
 42→        public ObjectType {
 43→            Objects.requireNonNull(fields, "fields must not be null");
 44→            fields = List.copyOf(fields);
 45→        }
 46→
 47→        /**
 48→         * Creates a {@link JlsmSchema} from this ObjectType's field definitions.
 49→         *
 50→         * @param name the schema name; must not be null
 51→         * @param version the schema version
 52→         * @return a new JlsmSchema with this ObjectType's fields
 53→         */
 54→        public JlsmSchema toSchema(String name, int version) {
 55→            Objects.requireNonNull(name, "name must not be null");
 56→            JlsmSchema.Builder builder = JlsmSchema.builder(name, version);
 57→            for (FieldDefinition fd : fields) {
 58→                builder.field(fd.name(), fd.type());
 59→            }
 60→            return builder.build();
 61→        }
 62→    }
 63→
 64→    // --- Static factory shortcuts ---
 65→
 66→    /** Returns {@link Primitive#STRING}. */
 67→    static FieldType string() {
 68→        return Primitive.STRING;
 69→    }
 70→
 71→    /** Returns {@link Primitive#INT32}. */
 72→    static FieldType int32() {
 73→        return Primitive.INT32;
 74→    }
 75→
 76→    /** Returns {@link Primitive#INT64}. */
 77→    static FieldType int64() {
 78→        return Primitive.INT64;
 79→    }
 80→
 81→    /** Returns {@link Primitive#FLOAT32}. */
 82→    static FieldType float32() {
 83→        return Primitive.FLOAT32;
 84→    }
 85→
 86→    /** Returns {@link Primitive#FLOAT64}. */
 87→    static FieldType float64() {
 88→        return Primitive.FLOAT64;
 89→    }
 90→
 91→    /** Returns {@link Primitive#BOOLEAN}. */
 92→    static FieldType boolean_() {
 93→        return Primitive.BOOLEAN;
 94→    }
 95→
 96→    /** Returns {@link Primitive#TIMESTAMP}. */
 97→    static FieldType timestamp() {
 98→        return Primitive.TIMESTAMP;
 99→    }
100→
101→    /**
102→     * Returns an {@link ArrayType} with the given element type.
103→     *
104→     * @param elementType the element type; must not be null
105→     * @return a new ArrayType
106→     */
107→    static FieldType arrayOf(FieldType elementType) {
108→        assert elementType != null : "elementType must not be null";
109→        return new ArrayType(elementType);
110→    }
111→
112→    /**
113→     * Returns an {@link ObjectType} with the given field definitions.
114→     *
115→     * @param fields the field definitions; must not be null
116→     * @return a new ObjectType
117→     */
118→    static FieldType objectOf(List<FieldDefinition> fields) {
119→        assert fields != null : "fields must not be null";
120→        return new ObjectType(fields);
121→    }
122→}
