 18→    private static JlsmSchema testSchema() {
 19→        return JlsmSchema.builder("test", 1).field("name", FieldType.Primitive.STRING)
 20→                .field("age", FieldType.Primitive.INT32).build();
 21→    }
 22→
 23→    private static MemorySegment stringKey(String key) {
 24→        byte[] bytes = key.getBytes(java.nio.charset.StandardCharsets.UTF_8);
 25→        MemorySegment seg = Arena.ofAuto().allocate(bytes.length);
 26→        seg.copyFrom(MemorySegment.ofArray(bytes));
 27→        return seg;
 28→    }
 29→
 30→    private static <T> List<T> collect(Iterator<T> it) {
 31→        var result = new ArrayList<T>();
 32→        it.forEachRemaining(result::add);
 33→        return result;
 34→    }
 35→
 36→    // ── Constructor validation ──────────────────────────────────────────
 37→
 38→    @Test
