 40→        var registry = new IndexRegistry(testSchema(), List.of());
 41→        assertThrows(NullPointerException.class, () -> new QueryExecutor<String>(null, registry));
 42→        registry.close();
 43→    }
 44→
 45→    @Test
 46→    void testConstructorRejectsNullRegistry() {
 47→        assertThrows(NullPointerException.class,
 48→                () -> new QueryExecutor<String>(testSchema(), null));
 49→    }
 50→
 51→    // ── Index-backed execution ──────────────────────────────────────────
 52→
 53→    @Test
 54→    void testIndexedEqUsesIndexLookup() throws IOException {
 55→        var schema = testSchema();
 56→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY));
 57→        var registry = new IndexRegistry(schema, defs);
 58→
 59→        // Insert test data via registry
 60→        var doc1 = JlsmDocument.of(schema, "name", "Alice", "age", 30);
 61→        var doc2 = JlsmDocument.of(schema, "name", "Bob", "age", 25);
 62→        var doc3 = JlsmDocument.of(schema, "name", "Alice", "age", 35);
 63→
 64→        registry.onInsert(stringKey("pk1"), doc1);
 65→        registry.onInsert(stringKey("pk2"), doc2);
 66→        registry.onInsert(stringKey("pk3"), doc3);
 67→
 68→        var executor = new QueryExecutor<String>(schema, registry);
 69→        var results = collect(executor.execute(new Predicate.Eq("name", "Alice")));
 70→
 71→        assertEquals(2, results.size(), "Should find 2 entries with name=Alice");
 72→
 73→        registry.close();
 74→    }
 75→
 76→    // ── And / Or composite execution ────────────────────────────────────
 77→
 78→    @Test
 79→    void testAndIntersectsChildren() throws IOException {
 80→        var schema = testSchema();
 81→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY),
 82→                new IndexDefinition("age", IndexType.RANGE));
 83→        var registry = new IndexRegistry(schema, defs);
 84→
 85→        var doc1 = JlsmDocument.of(schema, "name", "Alice", "age", 30);
 86→        var doc2 = JlsmDocument.of(schema, "name", "Alice", "age", 20);
 87→        var doc3 = JlsmDocument.of(schema, "name", "Bob", "age", 30);
 88→
 89→        registry.onInsert(stringKey("pk1"), doc1);
 90→        registry.onInsert(stringKey("pk2"), doc2);
 91→        registry.onInsert(stringKey("pk3"), doc3);
 92→
 93→        var executor = new QueryExecutor<String>(schema, registry);
 94→        var predicate = new Predicate.And(
 95→                List.of(new Predicate.Eq("name", "Alice"), new Predicate.Gte("age", 25)));
 96→
 97→        var results = collect(executor.execute(predicate));
 98→        assertEquals(1, results.size(), "Only pk1 (Alice, 30) matches both predicates");
 99→
100→        registry.close();
101→    }
102→
103→    @Test
104→    void testOrUnionsChildren() throws IOException {
105→        var schema = testSchema();
106→        var defs = List.of(new IndexDefinition("name", IndexType.EQUALITY));
107→        var registry = new IndexRegistry(schema, defs);
108→
109→        var doc1 = JlsmDocument.of(schema, "name", "Alice", "age", 30);
110→        var doc2 = JlsmDocument.of(schema, "name", "Bob", "age", 25);
111→        var doc3 = JlsmDocument.of(schema, "name", "Carol", "age", 35);
112→
113→        registry.onInsert(stringKey("pk1"), doc1);
114→        registry.onInsert(stringKey("pk2"), doc2);
115→        registry.onInsert(stringKey("pk3"), doc3);
116→
117→        var executor = new QueryExecutor<String>(schema, registry);
118→        var predicate = new Predicate.Or(
119→                List.of(new Predicate.Eq("name", "Alice"), new Predicate.Eq("name", "Bob")));
120→
121→        var results = collect(executor.execute(predicate));
122→        assertEquals(2, results.size(), "Should find Alice and Bob via union");
123→
124→        registry.close();
125→    }
