 21→/**
 22→ * Secondary index for equality, range, and unique lookups on a single field. Uses an in-memory
 23→ * sorted map where keys are sort-preserving encoded field values (via {@link FieldValueCodec}) and
 24→ * values are lists of primary keys.
 25→ */
 26→public final class FieldIndex implements SecondaryIndex {
 27→
 28→    private final IndexDefinition definition;
 29→    private final NavigableMap<ByteArrayKey, List<MemorySegment>> entries;
 30→    private volatile boolean closed;
 31→
 32→    public FieldIndex(IndexDefinition definition) throws IOException {
 33→        Objects.requireNonNull(definition, "definition");
 34→        IndexType type = definition.indexType();
 35→        assert type == IndexType.EQUALITY || type == IndexType.RANGE || type == IndexType.UNIQUE
 36→                : "FieldIndex only supports EQUALITY, RANGE, or UNIQUE";
 37→        this.definition = definition;
 38→        this.entries = new TreeMap<>();
 39→    }
 40→
 41→    @Override
 42→    public IndexDefinition definition() {
 43→        return definition;
 44→    }
 45→
 46→    @Override
 47→    public void onInsert(MemorySegment primaryKey, Object fieldValue) throws IOException {
 48→        assert !closed : "Index is closed";
 49→        if (fieldValue == null) {
 50→            return;
 51→        }
 52→        FieldType fieldType = inferFieldType(fieldValue);
 53→        ByteArrayKey encoded = encodeKey(fieldValue, fieldType);
 54→
 55→        if (definition.indexType() == IndexType.UNIQUE) {
 56→            List<MemorySegment> existing = entries.get(encoded);
 57→            if (existing != null && !existing.isEmpty()) {
 58→                throw new DuplicateKeyException(String.valueOf(fieldValue));
 59→            }
 60→        }
 61→
 62→        entries.computeIfAbsent(encoded, _ -> new ArrayList<>()).add(copySegment(primaryKey));
 63→    }
 64→
 65→    @Override
 66→    public void onUpdate(MemorySegment primaryKey, Object oldFieldValue, Object newFieldValue)
 67→            throws IOException {
 68→        assert !closed : "Index is closed";
 69→        if (oldFieldValue != null) {
 70→            removeEntry(primaryKey, oldFieldValue);
 71→        }
 72→        if (newFieldValue != null) {
 73→            onInsert(primaryKey, newFieldValue);
 74→        }
 75→    }
 76→
 77→    @Override
 78→    public void onDelete(MemorySegment primaryKey, Object fieldValue) throws IOException {
 79→        assert !closed : "Index is closed";
 80→        if (fieldValue == null) {
 81→            return;
 82→        }
 83→        removeEntry(primaryKey, fieldValue);
 84→    }
 85→
 86→    @Override
 87→    public Iterator<MemorySegment> lookup(Predicate predicate) throws IOException {
 88→        assert !closed : "Index is closed";
 89→        return switch (predicate) {
 90→            case Predicate.Eq eq -> lookupEq(eq.value());
 91→            case Predicate.Ne ne -> lookupNe(ne.value());
 92→            case Predicate.Gt gt -> lookupGt(gt.value());
 93→            case Predicate.Gte gte -> lookupGte(gte.value());
 94→            case Predicate.Lt lt -> lookupLt(lt.value());
 95→            case Predicate.Lte lte -> lookupLte(lte.value());
 96→            case Predicate.Between between -> lookupBetween(between.low(), between.high());
 97→            default -> Collections.emptyIterator();
 98→        };
 99→    }
100→
101→    @Override
102→    public boolean supports(Predicate predicate) {
103→        String field = predicateField(predicate);
104→        if (field == null || !field.equals(definition.fieldName())) {
105→            return false;
106→        }
107→        return switch (definition.indexType()) {
108→            case EQUALITY -> predicate instanceof Predicate.Eq || predicate instanceof Predicate.Ne;
109→            case RANGE, UNIQUE -> predicate instanceof Predicate.Eq
110→                    || predicate instanceof Predicate.Ne || predicate instanceof Predicate.Gt
111→                    || predicate instanceof Predicate.Gte || predicate instanceof Predicate.Lt
112→                    || predicate instanceof Predicate.Lte || predicate instanceof Predicate.Between;
113→            default -> false;
114→        };
115→    }
116→
117→    @Override
118→    public void close() throws IOException {
119→        closed = true;
120→        entries.clear();

